* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.game-container {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  max-width: 480px;
  margin: 0 auto;
  padding: 20px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 40px;
}

.game-header h1 {
  font-size: 2.5rem;
  font-weight: 700;
  background: linear-gradient(45deg, #ffd700, #ffed4e);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.streak {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(255, 255, 255, 0.1);
  padding: 10px 20px;
  border-radius: 12px;
  backdrop-filter: blur(10px);
}

.streak-label {
  font-size: 0.875rem;
  opacity: 0.8;
}

.streak-value {
  font-size: 2rem;
  font-weight: 700;
  color: #ffd700;
}

.game-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 40px;
}

.price-display {
  background: rgba(255, 255, 255, 0.1);
  padding: 30px;
  border-radius: 20px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  text-align: center;
}

.current-price {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.price-label {
  font-size: 1.125rem;
  opacity: 0.8;
}

.price-value {
  font-size: 3rem;
  font-weight: 700;
  color: #00ff88;
  text-shadow: 0 0 20px rgba(0, 255, 136, 0.3);
}

.game-info {
  margin-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 12px;
}

.start-price {
  font-size: 0.875rem;
  opacity: 0.8;
}

.timer {
  font-size: 2rem;
  font-weight: 700;
  color: #ff6b6b;
  animation: pulse 1s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.prediction {
  font-size: 1.125rem;
  font-weight: 600;
}

.result {
  margin-top: 30px;
  text-align: center;
}

.result-badge {
  font-size: 1.5rem;
  font-weight: 700;
  padding: 15px 30px;
  border-radius: 12px;
  margin-bottom: 20px;
  display: inline-block;
}

.result-badge.win {
  background: linear-gradient(45deg, #00ff88, #00cc6a);
  color: white;
}

.result-badge.lose {
  background: linear-gradient(45deg, #ff6b6b, #ee5a52);
  color: white;
}

.price-change {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 1rem;
}

.price-change .positive {
  color: #00ff88;
  font-weight: 600;
}

.price-change .negative {
  color: #ff6b6b;
  font-weight: 600;
}

.game-controls {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 30px;
}

.prediction-buttons {
  text-align: center;
  width: 100%;
}

.prediction-buttons h2 {
  font-size: 1.5rem;
  margin-bottom: 30px;
  line-height: 1.4;
}

.prediction-buttons {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.btn {
  padding: 20px 40px;
  border: none;
  border-radius: 16px;
  font-size: 1.25rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(10px);
  border: 2px solid transparent;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-up {
  background: linear-gradient(45deg, #00ff88, #00cc6a);
  color: white;
}

.btn-up:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 10px 25px rgba(0, 255, 136, 0.3);
}

.btn-down {
  background: linear-gradient(45deg, #ff6b6b, #ee5a52);
  color: white;
}

.btn-down:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 10px 25px rgba(255, 107, 107, 0.3);
}

.btn-primary {
  background: linear-gradient(45deg, #667eea, #764ba2);
  color: white;
  border: 2px solid rgba(255, 255, 255, 0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 25px rgba(102, 126, 234, 0.3);
}

.playing-state {
  text-align: center;
}

.countdown-circle {
  width: 120px;
  height: 120px;
  border: 4px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
}

.countdown-text {
  font-size: 2.5rem;
  font-weight: 700;
  color: #ffd700;
}

.streak-info {
  text-align: center;
  background: rgba(255, 255, 255, 0.1);
  padding: 20px;
  border-radius: 12px;
  backdrop-filter: blur(10px);
}

.streak-info p {
  font-size: 1.125rem;
  font-weight: 600;
  color: #ffd700;
  margin-bottom: 5px;
}

.streak-info small {
  opacity: 0.7;
}

@media (max-width: 480px) {
  .game-container {
    padding: 15px;
  }

  .game-header h1 {
    font-size: 2rem;
  }

  .price-value {
    font-size: 2.5rem;
  }

  .game-info {
    flex-direction: column;
    gap: 15px;
  }

  .prediction-buttons h2 {
    font-size: 1.25rem;
  }
}

