import './App.css'

// Helper function to call Pyth MCP Server
async function pythMCP(toolName, args) {
  try {
    // Step 1: Initialize session
    const init = await fetch('https://mcp.pyth.network/mcp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 0, method: 'initialize',
        params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'daddsad-game', version: '1.0' } }
      })
    });
    await init.json();

    // Step 2: Call the tool
    const res = await fetch('https://mcp.pyth.network/mcp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 1, method: 'tools/call',
        params: { name: toolName, arguments: args }
      })
    });
    const data = await res.json();
    const text = data.result?.content?.[0]?.text || '';
    return JSON.parse(text);
  } catch (error) {
    console.error('Pyth MCP error:', error);
    return null;
  }
}

function App() {
  const [btcPrice, setBtcPrice] = useState(null)
  const [gameState, setGameState] = useState('waiting') // waiting, playing, finished
  const [prediction, setPrediction] = useState(null) // 'up' or 'down'
  const [startPrice, setStartPrice] = useState(null)
  const [endPrice, setEndPrice] = useState(null)
  const [streak, setStreak] = useState(0)
  const [timeLeft, setTimeLeft] = useState(30)
  const [result, setResult] = useState(null) // 'win' or 'lose'

  // Fetch BTC price every 2 seconds
  useEffect(() => {
    const fetchPrice = async () => {
      const data = await pythMCP('get_historical_price', {
        symbols: ['Crypto.BTC/USD'],
        timestamp: Math.floor(Date.now() / 1000)
      });
      if (data && data['Crypto.BTC/USD']) {
        setBtcPrice(data['Crypto.BTC/USD'].price);
      }
    };

    fetchPrice(); // Initial fetch
    const interval = setInterval(fetchPrice, 2000);
    return () => clearInterval(interval);
  }, []);

  // Game timer
  useEffect(() => {
    let timer;
    if (gameState === 'playing' && timeLeft > 0) {
      timer = setTimeout(() => {
        setTimeLeft(timeLeft - 1);
      }, 1000);
    } else if (gameState === 'playing' && timeLeft === 0) {
      endGame();
    }
    return () => clearTimeout(timer);
  }, [gameState, timeLeft]);

  const startGame = (userPrediction) => {
    if (!btcPrice) return;

    setPrediction(userPrediction);
    setStartPrice(btcPrice);
    setGameState('playing');
    setTimeLeft(30);
    setResult(null);
    setEndPrice(null);
  };

  const endGame = () => {
    if (!btcPrice || !startPrice) return;

    setEndPrice(btcPrice);
    const priceWentUp = btcPrice > startPrice;
    const isCorrect = (prediction === 'up' && priceWentUp) || (prediction === 'down' && !priceWentUp);

    if (isCorrect) {
      setStreak(streak + 1);
      setResult('win');
    } else {
      setStreak(Math.floor(streak / 2)); // Drop by half
      setResult('lose');
    }

    setGameState('finished');
  };

  const playAgain = () => {
    setGameState('waiting');
    setPrediction(null);
    setStartPrice(null);
    setEndPrice(null);
    setResult(null);
  };

  const formatPrice = (price) => {
    return price ? `$${price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : '$--,---';
  };

  const getPriceChange = () => {
    if (!startPrice || !endPrice) return { amount: 0, percentage: 0 };
    const amount = endPrice - startPrice;
    const percentage = (amount / startPrice) * 100;
    return { amount, percentage };
  };

  return (
    <div className="game-container">
      <header className="game-header">
        <h1>daddsad</h1>
        <div className="streak">
          <span className="streak-label">Streak:</span>
          <span className="streak-value">{streak}</span>
        </div>
      </header>

      <main className="game-main">
        <div className="price-display">
          <div className="current-price">
            <span className="price-label">Bitcoin Price</span>
            <span className="price-value">{formatPrice(btcPrice)}</span>
          </div>

          {gameState === 'playing' && (
            <div className="game-info">
              <div className="start-price">
                Start: {formatPrice(startPrice)}
              </div>
              <div className="timer">
                {timeLeft}s
              </div>
              <div className="prediction">
                Prediction: {prediction === 'up' ? '📈 UP' : '📉 DOWN'}
              </div>
            </div>
          )}

          {gameState === 'finished' && (
            <div className="result">
              <div className={`result-badge ${result}`}>
                {result === 'win' ? '🎉 CORRECT!' : '❌ WRONG'}
              </div>
              <div className="price-change">
                <div>Start: {formatPrice(startPrice)}</div>
                <div>End: {formatPrice(endPrice)}</div>
                <div className={getPriceChange().amount >= 0 ? 'positive' : 'negative'}>
                  {getPriceChange().amount >= 0 ? '+' : ''}${getPriceChange().amount.toFixed(2)} 
                  ({getPriceChange().percentage >= 0 ? '+' : ''}{getPriceChange().percentage.toFixed(3)}%)
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="game-controls">
          {gameState === 'waiting' && (
            <div className="prediction-buttons">
              <h2>Will Bitcoin go UP or DOWN in 30 seconds?</h2>
              <button 
                className="btn btn-up" 
                onClick={() => startGame('up')}
                disabled={!btcPrice}
              >
                📈 UP
              </button>
              <button 
                className="btn btn-down" 
                onClick={() => startGame('down')}
                disabled={!btcPrice}
              >
                📉 DOWN
              </button>
            </div>
          )}

          {gameState === 'playing' && (
            <div className="playing-state">
              <div className="countdown-circle">
                <div className="countdown-text">{timeLeft}</div>
              </div>
              <p>Watching the price...</p>
            </div>
          )}

          {gameState === 'finished' && (
            <button className="btn btn-primary" onClick={playAgain}>
              Play Again
            </button>
          )}
        </div>

        {streak > 0 && (
          <div className="streak-info">
            <p>🔥 {streak} correct prediction{streak !== 1 ? 's' : ''} in a row!</p>
            <small>Wrong prediction drops your streak by half</small>
          </div>
        )}
      </main>
    </div>
  )
}

export default App"}

